{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-dleycW/src/address.js","content":"// Cell address helpers: parsing, normalizing, ordering.

/** Convert a 1- or 2-letter column string to its 1-based number (A=1 ... ZZ=702). */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64) // 'A' -> 1
  }
  return n
}

/** Convert a 1-based column number back to its letter form. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parse a word as a cell address. Returns { key, col, row } when the word is
 * a valid, addressable cell reference (case-insensitive), or null otherwise.
 */
export function parseAddressWord(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const rowNum = parseInt(m[2], 10)
  if (rowNum < 1) return null
  const colLetters = m[1].toUpperCase()
  const col = colToNum(colLetters)
  const key = colLetters + String(rowNum)
  return { key, col, row: rowNum }
}

/** Comparator for cell keys: ascending column, then ascending row. */
export function compareKeys(a, b) {
  const pa = parseAddressWord(a)
  const pb = parseAddressWord(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

