{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-dleycW/src/lexer.js","content":"// Tokenizer for formula bodies (the part of the content after the leading '=').

export class GrammarError extends Error {}

const SIMPLE = {
  '(': 'LPAREN',
  ')': 'RPAREN',
  ',': 'COMMA',
  ':': 'COLON',
  '+': 'PLUS',
  '-': 'MINUS',
  '*': 'STAR',
  '/': 'SLASH',
  '^': 'CARET',
}

/**
 * Turn a formula body into a flat token list.
 * Throws GrammarError on any character the grammar does not accept.
 */
export function tokenize(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      if (body[j] === '.' && j + 1 < n && body[j + 1] >= '0' && body[j + 1] <= '9') {
        j++
        while (j < n && body[j] >= '0' && body[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', text: body.slice(i, j) })
      i = j
      continue
    }
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(body[j])) j++
      tokens.push({ type: 'IDENT', text: body.slice(i, j) })
      i = j
      continue
    }
    if (ch === '<') {
      if (body[i + 1] === '>') {
        tokens.push({ type: 'NE', text: '<>' })
        i += 2
      } else if (body[i + 1] === '=') {
        tokens.push({ type: 'LE', text: '<=' })
        i += 2
      } else {
        tokens.push({ type: 'LT', text: '<' })
        i += 1
      }
      continue
    }
    if (ch === '>') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'GE', text: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'GT', text: '>' })
        i += 1
      }
      continue
    }
    if (ch === '=') {
      tokens.push({ type: 'EQ', text: '=' })
      i += 1
      continue
    }
    if (SIMPLE[ch]) {
      tokens.push({ type: SIMPLE[ch], text: ch })
      i += 1
      continue
    }
    throw new GrammarError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

