{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-dleycW/src/parser.js","content":"// Recursive-descent parser for formula bodies.
import { tokenize, GrammarError } from './lexer.js'

const COMPARE_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const COMPARE_OP = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  advance() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new GrammarError(`expected ${type}`)
    return this.advance()
