export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function numberValue(v) {
  return { type: 'number', value: v }
}
export function textValue(v) {
  return { type: 'text', value: v }
}
export function boolValue(v) {
  return { type: 'bool', value: v }
}
export function errorValue(v) {
  return { type: 'error', value: v }
}

export const ERR_ERR = errorValue('#ERR!')
export const ERR_REF = errorValue('#REF!')
export const ERR_VALUE = errorValue('#VALUE!')
export const ERR_DIV0 = errorValue('#DIV/0!')
export const ERR_NAME = errorValue('#NAME?')
export const ERR_CYCLE = errorValue('#CYCLE!')

/** Read a value in an arithmetic position: number stays, bool -> 1/0, text -> #VALUE!, error passes through. */
export function toNumber(v) {
  if (v.type === 'error') return v
  if (v.type === 'number') return v
  if (v.type === 'bool') return numberValue(v.value ? 1 : 0)
  return ERR_VALUE
}

/** Rank for cross-type comparisons: number < text < bool. */
function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

/** Compare two non-error values per the spec's ordering rules. Returns <0, 0, >0. */
export function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 0) return a.value - b.value
  if (ra === 1) return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}

/** Format a finite number per spec: round to 10 significant digits, print as JS would. */
export function formatNumber(x) {
  if (x === 0) return '0'
  let rounded = Number(x.toPrecision(10))
  if (Object.is(rounded, -0)) rounded = 0
  return String(rounded)
}

export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'text':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    default:
      throw new Error('unknown value type')
  }
}
