import { parseFormula, GrammarError } from './parser.js'
import { numberValue, textValue, ERROR_TOKENS, errorValue } from './values.js'

export class SheetError extends Error {
  constructor(lineNumber, message) {
    super(message)
    this.lineNumber = lineNumber
  }
