    let content
    if (sepIndex === -1) {
      addressText = stripped
      content = ''
    } else {
      addressText = stripped.slice(0, sepIndex)
      let k = sepIndex
      while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
      content = stripped.slice(k)
    }

    const parsed = parseAddressWord(addressText)
    if (!parsed) {
      throw new SheetError(lineNumber, `invalid cell address ${addressText}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(lineNumber, `cell ${addressText} is declared twice`)
    }

    let record
    if (content.startsWith('=')) {
      let ast = null
      try {
        ast = parseFormula(content.slice(1))
      } catch (e) {
