{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-dleycW/src/evaluate.js","content":"// Formula evaluator with lazy, memoized, cycle-detecting cell resolution.
import { parseAddressWord, colToNum } from './address.js'
import {
  numberValue,
  boolValue,
  toNumber,
  compareValues,
  ERR_ERR,
  ERR_REF,
  ERR_VALUE,
  ERR_DIV0,
  ERR_NAME,
  ERR_CYCLE,
} from './values.js'

const AGGREGATE_FNS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function isFinite_(n) {
  return Number.isFinite(n)
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
  }

  getCell(key) {
    let cell = this.cells.get(key)
    if (!cell) {
      cell = { isFormula: false, ast: null, status: 'done', value: numberValue(0) }
      // Not stored: undeclared cells are not part of the declared set.
    }
    return cell
  }

  evaluateCell(key) {
    const cell = this.getCell(key)
    if (cell.status === 'done') return cell.value
    if (cell.status === 'visiting') return ERR_CYCLE
    if (cell.ast === null) {
      cell.value = ERR_ERR
      cell.status = 'done'
      return cell.value
    }
    cell.status = 'visiting'
    const result = this.evalExpr(cell.ast)
    cell.status = 'done'
    cell.value = result
    return result
  }

  resolveAddressValue(word) {
    const addr = parseAddressWord(word)
    if (!addr) return ERR_REF
    return this.evaluateCell(addr.key)
  }

  /** Expand a range node into the ordered list of cell values it covers. */
  expandRange(node) {
    const left = parseAddressWord(node.left)
    const right = parseAddressWord(node.right)
    if (!left || !right) return [ERR_REF]
    const colMin = Math.min(left.col, right.col)
    const colMax = Math.max(left.col, right.col)
    const rowMin = Math.min(left.row, right.row)
    const rowMax = Math.max(left.row, right.row)
    const out = []
    for (let c = colMin; c <= colMax; c++) {
      const colLetters = numToColLocal(c)
      for (let r = rowMin; r <= rowMax; r++) {
        out.push(this.evaluateCell(colLetters + String(r)))
      }
    }
    return out
  }

  /** Value of an argument that may or may not be a range; used by SUM/MIN/MAX/AVG/COUNT. */
  expandArgToList(node) {
    if (node.type === 'range') return this.expandRange(node)
    return [this.evalExpr(node)]
  }

  /** Reduce a possibly-multi-valued argument (range) down to a single value, for ABS/IF. */
  singleFromNode(node) {
    const list = this.expandArgToList(node)
    const firstErr = list.find((v) => v.type === 'error')
    if (firstErr) return firstErr
    if (list.length !== 1) return ERR_ERR
    return list[0]
  }

  evalExpr(node) {
    switch (node.type) {
      case 'number':
        return numberValue(node.value)
      case 'bool':
        return boolValue(node.value)
      case 'address':
        return this.resolveAddressValue(node.word)
      case 'range':
        return ERR_ERR
      case 'paren':
        return this.evalExpr(node.inner)
      case 'unary':
        return this.evalUnary(node)
      case 'binary':
        return this.evalBinary(node)
      case 'compare':
        return this.evalCompare(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evalExpr(node.arg)
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    const result = node.op === '-' ? -n.value : n.value
    if (!isFinite_(result)) return ERR_DIV0
    return numberValue(result)
  }

  evalBinary(node) {
    const leftVal = this.evalExpr(node.left)
    const rightVal = this.evalExpr(node.right)
    if (leftVal.type === 'error') return leftVal
    const leftNum = toNumber(leftVal)
    if (leftNum.type === 'error') return leftNum
    if (rightVal.type === 'error') return rightVal
    const rightNum = toNumber(rightVal)
    if (rightNum.type === 'error') return rightNum
    const a = leftNum.value
    const b = rightNum.value
    let result
    switch (node.op) {
      case '+':
        result = a + b
        break
      case '-':
        result = a - b
        break
      case '*':
        result = a * b
        break
      case '/':
        if (b === 0) return ERR_DIV0
        result = a / b
        break
      case '^':
        result = Math.pow(a, b)
        break
      default:
        throw new Error(`unknown op ${node.op}`)
    }
    if (!isFinite_(result)) return ERR_DIV0
    return numberValue(result)
  }

  evalCompare(node) {
    const leftVal = this.evalExpr(node.left)
    const rightVal = this.evalExpr(node.right)
    if (leftVal.type === 'error') return leftVal
    if (rightVal.type === 'error') return rightVal
    const cmp = compareValues(leftVal, rightVal)
    switch (node.op) {
      case '=':
        return boolValue(cmp === 0)
      case '<>':
        return boolValue(cmp !== 0)
      case '<':
        return boolValue(cmp < 0)
      case '<=':
        return boolValue(cmp <= 0)
      case '>':
        return boolValue(cmp > 0)
      case '>=':
        return boolValue(cmp >= 0)
      default:
        throw new Error(`unknown op ${node.op}`)
    }
  }

  evalCall(node) {
    const name = node.name
    const args = node.args

    if (name === 'ABS') {
      if (args.length !== 1) return ERR_ERR
      const v = this.singleFromNode(args[0])
      if (v.type === 'error') return v
      const n = toNumber(v)
      if (n.type === 'error') return n
      const result = Math.abs(n.value)
      if (!isFinite_(result)) return ERR_DIV0
      return numberValue(result)
    }

    if (name === 'IF') {
      if (args.length !== 3) return ERR_ERR
      const condVal = this.singleFromNode(args[0])
      if (condVal.type === 'error') return condVal
      let isTrue
      if (condVal.type === 'bool') isTrue = condVal.value
      else if (condVal.type === 'number') isTrue = condVal.value !== 0
      else return ERR_VALUE
      const branch = isTrue ? args[1] : args[2]
      return this.singleFromNode(branch)
    }

    if (AGGREGATE_FNS.has(name)) {
      if (args.length < 1) return ERR_ERR
      const flat = []
      for (const a of args) flat.push(...this.expandArgToList(a))

      if (name === 'COUNT') {
        const firstErr = flat.find((v) => v.type === 'error')
        if (firstErr) return firstErr
        return numberValue(flat.filter((v) => v.type === 'number').length)
      }

      const nums = flat.map(toNumber)
      const firstErr = nums.find((v) => v.type === 'error')
      if (firstErr) return firstErr
      const values = nums.map((v) => v.value)

      let result
      if (name === 'SUM') result = values.reduce((s, v) => s + v, 0)
      else if (name === 'AVG') result = values.reduce((s, v) => s + v, 0) / values.length
      else if (name === 'MIN') result = Math.min(...values)
      else if (name === 'MAX') result = Math.max(...values)

      if (!isFinite_(result)) return ERR_DIV0
      return numberValue(result)
    }

    return ERR_NAME
  }
}

function numToColLocal(n) {
