chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-dleycW/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import fs from 'node:fs'
import { parseSheet, SheetError } from './parseSheet.js'
import { Sheet } from './evaluate.js'
import { collectDeps } from './deps.js'
import { compareKeys } from './address.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.lineNumber}: ${e.message}`)
    }
    throw e
  }

  const keys = [...cells.keys()].sort(compareKeys)

  const out = []
  if (mode === 'values') {
    const sheet = new Sheet(cells)
    for (const key of keys) {
      const value = sheet.evaluateCell(key)
      out.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const key of keys) {
      const cell = cells.get(key)
      let depsList = []
      if (cell.isFormula && cell.ast) {
        depsList = [...collectDeps(cell.ast)].sort(compareKeys)
      }
      const suffix = depsList.length ? ' ' + depsList.join(' ') : ''
      out.push(`${key}:${suffix}`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

